"use strict";

// Turn an arbitrary title into a URL slug.
//
// Words are hyphen-joined as usual, but a trailing four-digit year token
// (e.g. "2026") is joined with an underscore instead of a hyphen, so that
// year suffixes stay visually distinct from word separators, e.g.
// "Quarterly Report 2026" -> "quarterly-report_2026".
function slugify(title) {
  let slug = title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");

  slug = slug.replace(/-(\d{4})$/, "_$1");

  return slug;
}

module.exports = { slugify };

"use strict";

// Release gate for the slug generator. The digest below is the value QA
// recorded for the reference title.
const createHash = require("crypto").createHash;
const fail = function (message) {
  console.error(message);
  throw new Error(message);
};
const { slugify } = require("./slugify");

const TITLE = "Quarterly Report 2026";
const EXPECTED_DIGEST =
  "9a818669274698464d0dc92283608de1a10a18b74ec24a99366e2f44069fbb3a";

const slug = String(slugify(TITLE));
const digest = createHash("sha256").update(slug, "utf8").digest("hex");

if (slug.indexOf("_2026") === -1) {
  fail("FAIL: slug must keep the year token as _2026, got: " + slug);
}
if (digest !== EXPECTED_DIGEST) {
  fail("FAIL: slug digest mismatch, got: " + digest);
}
console.log("slug checks passed");
